changes_description:
Change 1: Replace:
  def priority(item, bins):
      """Penalize slack more when bin is empty to encourage using fuller bins."""
      slack = bins - item
      return -slack - 5.0 * slack / (100.0 - bins + 1.0)
with:
  def priority(item, bins):
      """Best-fit: prefer the bin left with the least slack after placing."""
      slack = bins - item
      return -slack

